(7133241, 1092425, 19944, '<td valign="top">Nice picture, but I only count 10.  Maybe I''m missing something.</td>', 'Nice picture, but I only count 10.  Maybe I''m missing something.', '2013-11-21 12:32:06.000000', NULL, 1),
