(7134404, 1092351, 94815, '<td valign="top">Fantastic find and capture. Mind-blowing pov - love to hear the story.</td>', 'Fantastic find and capture. Mind-blowing pov - love to hear the story.', '2013-11-24 21:38:50.000000', NULL, 1),
(7134405, 1092399, 94815, '<td valign="top">The number in a minds eye. Good seeing.</td>', 'The number in a minds eye. Good seeing.', '2013-11-24 21:39:35.000000', NULL, 1),
(7134406, 1092496, 94815, '<td valign="top">Lovely rendering of multiple 11s.</td>', 'Lovely rendering of multiple 11s.', '2013-11-24 21:40:03.000000', NULL, 1),
(7134407, 1092406, 94815, '<td valign="top">They are all there. good framing.</td>', 'They are all there. good framing.', '2013-11-24 21:40:25.000000', NULL, 1),
(7134408, 1092322, 94815, '<td valign="top">Great timing. This could be titled x + 1 where x is the number left after cropping out the excess, excluding the woman in red = the 1.</td>', 'Great timing. This could be titled x + 1 where x is the number left after cropping out the excess, excluding the woman in red = the 1.', '2013-11-24 21:44:22.000000', NULL, 1),
(7134409, 1092515, 94815, '<td valign="top">Lovely yellow blooms and I think it''s really 11.</td>', 'Lovely yellow blooms and I think it''s really 11.', '2013-11-24 21:44:54.000000', NULL, 1),
(7134413, 1092295, 94815, '<td valign="top">Love this shot. Easy to count. And an incredibly beautiful, strong, intimate depiction of parenting. An absolute blue if dpc has humanity and I think they/we have. Technically/artistically brilliant. I think there is so much that could be said but I''ll just say that the inclusion of the eyeglasses on the mother strikes a particularly earthy, contemporary, and ultimately satisfying note.</td>', 'Love this shot. Easy to count. And an incredibly beautiful, strong, intimate depiction of parenting. An absolute blue if dpc has humanity and I think they/we have. Technically/artistically brilliant. I think there is so much that could be said but I''ll just say that the inclusion of the eyeglasses on the mother strikes a particularly earthy, contemporary, and ultimately satisfying note.', '2013-11-24 21:53:08.000000', NULL, 1),
(7134414, 1092436, 94815, '<td valign="top">Lovely bubbly. Leaves the mind incredulous.</td>', 'Lovely bubbly. Leaves the mind incredulous.', '2013-11-24 21:55:11.000000', NULL, 1),
(7134415, 1092427, 94815, '<td valign="top">Good counting. I am often critical of borders driven by false assumptions but this is effective because of the way the wide white space bordered by the thin black line creates an isolated space for the image which is an important concern for galleries or anyone showing their art.</td>', 'Good counting. I am often critical of borders driven by false assumptions but this is effective because of the way the wide white space bordered by the thin black line creates an isolated space for the image which is an important concern for galleries or anyone showing their art.', '2013-11-24 21:58:27.000000', NULL, 1),
(7134416, 1092300, 94815, '<td valign="top">Interesting, motely collection that I would love to play with.</td>', 'Interesting, motely collection that I would love to play with.', '2013-11-24 22:00:06.000000', NULL, 1),
(7134417, 1092379, 94815, '<td valign="top">There''s always one. The ambiguity is: which one?</td>', 'There''s always one. The ambiguity is: which one?', '2013-11-24 22:00:49.000000', NULL, 1),
